{
  "status": "SUPPORTED",
  "task_summary": "Locate fastening hardware and tools, secure the assembly, and return the tool.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "agent",
        "entity_kind": "OBJECT",
        "function": "The robot performing the manipulation and inspection tasks.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["robot", "arm"],
        "required_properties": ["ability to grasp", "ability to open containers"]
      },
      {
        "id": "fastener",
        "entity_kind": "OBJECT",
        "function": "The screw, bolt, or nut needed to secure the assembly.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["screw", "bolt", "nut", "hardware"],
        "required_properties": ["threaded", "rigid"]
      },
      {
        "id": "workpiece",
        "entity_kind": "OBJECT",
        "function": "The object being fastened (the yellow and black assembly).",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["assembly", "part", "block"],
        "required_properties": ["receives fastener", "situated on table"]
      },
      {
        "id": "tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to apply the fastener (wrench, screwdriver).",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["wrench", "screwdriver", "driver"],
        "required_properties": ["grasps fastener", "turns fastener"]
      },
      {
        "id": "storage_container",
        "entity_kind": "REGION",
        "function": "A closed or hidden space potentially holding the fastener or tool.",
        "required_count": 3,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["drawer", "cabinet", "compartment"],
        "required_properties": ["enclosed", "searchable"]
      },
      {
        "id": "fastening_site",
        "entity_kind": "REGION",
        "function": "The specific location on the workbench where the fastener is installed.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["spot", "hole", "location"],
        "required_properties": ["on workbench", "near workpiece"]
      },
      {
        "id": "rest_area",
        "entity_kind": "REGION",
        "function": "The general workbench surface where the tool is left.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["surface", "tabletop"],
        "required_properties": ["flat", "stable"]
      }
    ],
    "functional_relations": [
      {
        "id": "relation_1",
        "relation": "fits",
        "participant_roles": ["fastener", "workpiece"],
        "required": true
      },
      {
        "id": "relation_2",
        "relation": "operates",
        "participant_roles": ["tool", "fastener"],
        "required": true
      },
      {
        "id": "relation_3",
        "relation": "located_at",
        "participant_roles": ["fastener", "fastening_site"],
        "required": true
      },
      {
        "id": "relation_4",
        "relation": "located_at",
        "participant_roles": ["tool", "rest_area"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "operation_1",
        "operation": "Inspect storage container",
        "participant_roles": ["agent", "storage_container"]
      ,
      "operation_count": 3
      },
      {
        "id": "operation_2",
        "operation": "Retrieve fastener",
        "participant_roles": ["agent", "fastener", "storage_container"]
      ,
      "operation_count": 1
      },
      {
        "id": "operation_3",
        "operation": "Retrieve tool",
        "participant_roles": ["agent", "tool", "storage_container"]
      ,
      "operation_count": 1
      },
      {
        "id": "operation_4",
        "operation": "Install fastener",
        "participant_roles": ["agent", "fastener", "workpiece"]
      ,
      "operation_count": 1
      },
      {
        "id": "operation_5",
        "operation": "Tighten fastener",
        "participant_roles": ["agent", "tool", "fastener"]
      ,
      "operation_count": 1
      },
      {
        "id": "operation_6",
        "operation": "Place tool",
        "participant_roles": ["agent", "tool", "rest_area"]
      ,
      "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "agent": [
        {
          "label": "white robotic arm",
          "visual_description": "Large white articulated arm visible in foreground and side views."
        }
      ],
      "workpiece": [
        {
          "label": "yellow and black assembly",
          "visual_description": "Rectangular object with yellow top and black base sitting on the table."
        }
      ],
      "storage_container": [
        {
          "label": "blue cabinet",
          "visual_description": "Tall blue cabinet standing behind the table."
        },
        {
          "label": "left drawer",
          "visual_description": "Blue drawer underneath the left side of the table."
        },
        {
          "label": "right drawer",
          "visual_description": "Blue drawer underneath the right side of the table."
        }
      ],
      "fastening_site": [
        {
          "label": "table surface near assembly",
          "visual_description": "Wooden table surface immediately surrounding the yellow/black object."
        }
      ],
      "rest_area": [
        {
          "label": "table surface",
          "visual_description": "The entire wooden top of the workbench."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "blue_cabinet",
        "label": "blue cabinet",
        "visual_description": "Closed blue cabinet behind the table.",
        "reason": "Likely contains tools or spare components given its size and proximity to the workbench."
      },
      {
        "id": "left_drawer",
        "label": "left drawer",
        "visual_description": "Closed drawer under the table.",
        "reason": "Standard storage location for small tools or fasteners."
      },
      {
        "id": "right_drawer",
        "label": "right drawer",
        "visual_description": "Closed drawer under the table.",
        "reason": "Standard storage location for small tools or fasteners."
      }
    ],
    "inspection_order": [
      "blue_cabinet",
      "left_drawer",
      "right_drawer"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
